<h2>Compare margin, markup and target price</h2><p class="lead">See the difference between gross margin and markup using the same cost and selling price.</p><div class="form-grid"><div class="field"><label for="cost">Unit cost</label><input id="cost" type="number" min="0" step="0.01" value="60"></div><div class="field"><label for="price">Selling price</label><input id="price" type="number" min="0" step="0.01" value="100"></div><div class="field full"><label for="target">Target gross margin (%)</label><input id="target" type="number" min="0" max="99.99" step="0.01" value="40"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc">Calculate</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Gross profit</span><strong id="profit">—</strong></div><div class="metric"><span>Gross margin</span><strong id="margin">—</strong></div><div class="metric"><span>Markup</span><strong id="markup">—</strong></div><div class="metric"><span>Price for target margin</span><strong id="targetPrice">—</strong></div></div></div>
<script>(()=>{const $=i=>document.getElementById(i),n=i=>parseFloat($(i).value)||0,m=x=>'$'+x.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function go(){const c=n('cost'),p=n('price'),t=n('target')/100,profit=p-c;$('profit').textContent=m(profit);$('margin').textContent=p>0?(profit/p*100).toFixed(2)+'%':'—';$('markup').textContent=c>0?(profit/c*100).toFixed(2)+'%':'—';$('targetPrice').textContent=t<1?m(c/(1-t)):'—'}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('calc').onclick=go;go()})();</script>
